import {isVanity,vanitySettings} from './bathroom-cabinets.js?v=details-3';
// Finish studies are per design and per floor. Dimensions are inches.
export const TILE_ZONES={primary:'Primary bath floor',shower:'Primary shower walls',showerFloor:'Primary shower floor',shared:'Shared bath floor',laundry:'Laundry / powder floor',basement:'Basement bath floor'};
const tile=()=>({color:'#d8d1c2',grout:'#b7afa0',width:24,height:12,joint:.125,pattern:'stack',sheen:'matte'});
export function defaultSurfaces(){return {version:1,floorProduct:'saguaro',boardWidth:8,boardLength:75,trim:'white',direction:0,floorSheen:'matte',cabinetSheen:'matte',counterSheen:'honed',paintSheen:'eggshell',tiles:Object.fromEntries(Object.keys(TILE_ZONES).map(k=>[k,k==='showerFloor'?{...tile(),width:2,height:2}:tile()]))};}
export function ensureSurfaces(state){state.surfaces??=defaultSurfaces();const s=state.surfaces;if(!s.floorProduct){s.floorProduct='saguaro';s.boardWidth=8;s.floorSheen='matte';}s.boardLength??=75;s.trim??='white';s.tiles.showerFloor??={...tile(),width:2,height:2};return s;}
const hex=s=>typeof s==='string'&&/^#[0-9a-f]{6}$/i.test(s);
const number=(n,a,b)=>Number.isFinite(n)&&n>=a&&n<=b;
export function validSurfaces(s){return s===undefined||!!(s&&s.version===1&&(s.floorProduct!=='saguaro'||(s.boardWidth===8&&s.boardLength===75&&s.floorSheen==='matte'))&&(s.floorProduct===undefined||['saguaro','generic'].includes(s.floorProduct))&&(s.boardLength===undefined||number(s.boardLength,24,96))&&(s.trim===undefined||['white','oak','smoked','walnut'].includes(s.trim))&&number(s.boardWidth,3,12)&&[0,90].includes(s.direction)&&['matte','satin'].includes(s.floorSheen)&&['matte','satin'].includes(s.cabinetSheen)&&['honed','polished'].includes(s.counterSheen)&&['matte','eggshell','satin'].includes(s.paintSheen)&&s.tiles&&Object.keys(TILE_ZONES).every(k=>{const t=s.tiles[k];if(k==='showerFloor'&&t===undefined)return true;return t&&hex(t.color)&&hex(t.grout)&&number(t.width,2,48)&&number(t.height,2,48)&&number(t.joint,.0625,.375)&&['stack','offset'].includes(t.pattern)&&['matte','satin'].includes(t.sheen);}));}
export function snapshotFinishes(state){return structuredClone({finishes:state.finishes,surfaces:ensureSurfaces(state),makerFinish:state.kitchen?.maker?.finish??'rift-oak',stoneFinish:state.kitchen?.stone?.finish??'honed',kitchenDetails:state.kitchen?{hardware:state.kitchen.hardware,fixtures:state.kitchen.fixtures,stoneEdge:state.kitchen.stone?.edge??'eased'}:null,vanityFinishes:state.objects.filter(isVanity).map(o=>[o.id,vanitySettings(o).finish])});}
export function restoreFinishes(state,snapshot){state.finishes=structuredClone(snapshot.finishes);state.surfaces=structuredClone(snapshot.surfaces);if(state.kitchen){state.kitchen.maker??={};state.kitchen.maker.finish=snapshot.makerFinish;state.kitchen.stone??={};state.kitchen.stone.finish=snapshot.stoneFinish;if(snapshot.kitchenDetails){state.kitchen.hardware=snapshot.kitchenDetails.hardware;state.kitchen.fixtures=structuredClone(snapshot.kitchenDetails.fixtures);state.kitchen.stone.edge=snapshot.kitchenDetails.stoneEdge??'eased';}}for(const [id,finish] of snapshot.vanityFinishes){const o=state.objects.find(o=>o.id===id);if(o?.vanitySpec)o.vanitySpec.finish=finish;}}
export function setCabinetFinish(state,color){state.finishes.cabinet=color;const finish=color==='#64422d'?'walnut':['#e9e7e0','#263335'].includes(color)?'paint':'rift-oak';if(state.kitchen){state.kitchen.maker??={};state.kitchen.maker.finish=finish;}for(const o of state.objects){if(isVanity(o)){o.vanitySpec=vanitySettings(o);o.vanitySpec.finish=finish==='paint'?'white':finish==='walnut'?'walnut':'oak';}}}
export const PALETTES={
 warm:{name:'Warm & quiet',description:'White cabinets · clean white paint · ivory stone',cabinet:'#e9e7e0',wall:'#ffffff',counter:'#efede7',tile:'#ded7c9',grout:'#c3baaa'},
 natural:{name:'Oak & limestone',description:'Oak cabinets · putty paint · warm limestone',cabinet:'#986b43',wall:'#d8d2c4',counter:'#efede7',tile:'#cfc7b6',grout:'#b0a794'},
 contrast:{name:'Soft contrast',description:'Charcoal cabinets · soft white paint · pale gray stone',cabinet:'#263335',wall:'#f3f4f0',counter:'#efede7',tile:'#cdceca',grout:'#b6b8b1'}
};
export function applyPalette(state,key){const p=PALETTES[key];if(!p)return;setCabinetFinish(state,p.cabinet);state.finishes.wall=p.wall;state.finishes.counter=p.counter;const s=ensureSurfaces(state);s.cabinetSheen='matte';s.counterSheen='honed';s.paintSheen='eggshell';if(state.kitchen){state.kitchen.stone??={};state.kitchen.stone.finish='honed';}for(const t of Object.values(s.tiles)){t.color=p.tile;t.grout=p.grout;t.sheen='matte';}}
